        "unit": "mm",
        "method": "Synthetic wall-thickness check T",
        "minimum": "4",
        "maximum": "6",
        "required": true
      }
    ],
    "setups": [
      {
        "name": "A",
        "revision": 1,
        "materials": [
          {
            "name": "Recovered HDPE matrix",
            "amount": "7",
            "unit": "kg"
          },
          {
            "name": "Cork filler",
            "amount": "3",
            "unit": "kg"
          }
        ],
        "process": "Fictional compression-molding process P; settings unspecified",
        "geometry": "Organizer tray; nominal footprint 200 by 80 mm"
      },
      {
        "name": "B",
        "revision": 1,
        "materials": [
          {
            "name": "Recovered HDPE matrix",
            "amount": "8",
            "unit": "kg"
          },
          {
            "name": "Cork filler",
            "amount": "2",
            "unit": "kg"
          }
        ],
        "process": "Fictional compression-molding process P; settings unspecified",
        "geometry": "Organizer tray; nominal footprint 200 by 80 mm"
      }
    ],
    "readings": [
      {
        "setup": "A",
        "revision": 1,
        "check": "deflection",
        "value": "3.8",
        "unit": "mm",
        "data_kind": "synthetic",
        "grouping": "unknown"
      },
      {
        "setup": "A",
        "revision": 1,
        "check": "wall_thickness",
        "value": "5.8",
        "unit": "mm",
        "data_kind": "synthetic",
        "grouping": "unknown"
      },
      {
        "setup": "B",
        "revision": 1,
        "check": "deflection",
        "value": "2.6",
        "unit": "mm",
        "data_kind": "synthetic",
        "grouping": "unknown"
      },
      {
        "setup": "B",
        "revision": 1,
        "check": "wall_thickness",
        "value": "5.4",
        "unit": "mm",
        "data_kind": "synthetic",
        "grouping": "unknown"
      }
    ],
    "costs": {
      "currency": "EUR",
      "mass_basis": "as received",
      "prices_EUR_per_kg": {
        "Recovered HDPE matrix": "1.25",
        "Cork filler": "0.50"
      },
      "scope": "Materials only. Energy, direct labor and all other costs are explicitly excluded.",
      "functional_basis": "The same nominal desk cable organizer and indoor use in both setups.",
      "acceptance_basis": "A tray meeting the two stated checks; the counts below are fictional planning assumptions, not observed accepted output.",
      "output_mode": "planned",
      "gross_planned_items_per_setup": "10",
      "assumed_accepted_fraction": "1"
    }
  },
  "independent_material_cost_calculations": {
    "A": {
      "material_inputs": [
        {
          "name": "Recovered HDPE matrix",
          "amount": "7",
          "unit": "kg"
        },
        {
          "name": "Cork filler",
          "amount": "3",
          "unit": "kg"
        }
      ],
      "prices_EUR_per_kg": {
        "Recovered HDPE matrix": "1.25",
        "Cork filler": "0.50"
      },
      "formula": "sum(component kg × price EUR/kg) / (gross planned items × accepted fraction)",
      "total_EUR_exact": "41/4",
      "usable_items_assumed": "10",
      "EUR_per_item_exact": "41/40"
    },
    "B": {
      "material_inputs": [
        {
          "name": "Recovered HDPE matrix",
          "amount": "8",
          "unit": "kg"
        },
        {
          "name": "Cork filler",
          "amount": "2",
          "unit": "kg"
        }
      ],
      "prices_EUR_per_kg": {
        "Recovered HDPE matrix": "1.25",
        "Cork filler": "0.50"
      },
      "formula": "sum(component kg × price EUR/kg) / (gross planned items × accepted fraction)",
      "total_EUR_exact": "11",
      "usable_items_assumed": "10",
      "EUR_per_item_exact": "11/10"
    }
  },
  "question": "Using only these synthetic records and materials-only planning costs, which setup is the recorded choice and what trade-off should I understand?"
}

